 } public function save_post($post_id, $post) { if (!empty($_POST[$this->setting_name])) { $value = array_filter($_REQUEST[$this->setting_name], array($this, 'is_not_empty')); update_post_meta( $post_id, $this->setting_name, $value ); } } public function register_taxonomy() { $plural_name = __( 'Collection Categories', $this->text_domain); $singular_name = __( 'Collection Category', $this->text_domain); $labels = array( 'name' => $plural_name, 'singular_name' => $singular_name, 'menu_name' => $singular_name, 'all_items' => sprintf(__( 'All %s', $this->text_domain ), $singular_name ), 'edit_item' => sprintf(__( 'Edit %s', $this->text_domain ), $singular_name ), 'view_item' => sprintf(__( 'View %s', $this->text_domain ), $singular_name ), 'update_item' => sprintf(__( 'Update %s', $this->text_domain ), $singular_name ), 'add_new_item' => sprintf(__( 'Add New %s', $this->text_domain ), $singular_name ), 'new_item_name' => sprintf(__( 'New %s Name', $this->text_domain ), $singular_name ), 'parent_item' => sprintf(__( 'Parent %s', $this->text_domain ), $singular_name ), 'parent_item_colon' => sprintf(__( 'Parent %s', $this->text_domain ), $singular_name ), 'search_items' => sprintf(__('Search %s', $this->text_domain), $singular_name ), 'popular_items' => $plural_name, 'separate_items_with_commas' => sprintf(__('Separate %s with commas', $this->text_domain), $singular_name ), 'add_or_remove_items' => sprintf(__('Add or remove %s', $this->text_domain), $singular_name ), 'choose_from_most_used' => sprintf(__('Choose from the most used %s', $this->text_domain), $singular_name ), 'not_found' => sprintf(__('No %s found.', $this->text_domain), $singular_name ) ); $args = array( 'public' => false, 'hierarchical' => true, 'labels' => $labels, 'show_ui' => true, 'show_in_menu' => true, 'show_admin_column' => true, 'query_var' => false, 'rewrite' => array( 'slug' => $this->taxonomy ), ); register_taxonomy( $this->taxonomy, array($this->post_type), $args ); } public function admin_menu() { require __DIR__ . DIRECTORY_SEPARATOR. 'classes' . DIRECTORY_SEPARATOR . 'class.wp-list-table-parser.php'; if ( !apply_filters( 'qqworld-collector-activated', false ) ) return; if ( apply_filters( 'qqworld-collector-activated-license', false ) && !apply_filters( 'qqworld-collector-activated-module-' . $this->module, false ) ) return; $parent_slug = 'qqworld-collector'; $page_title = __('Collected Posts', $this->text_domain); $menu_title = __('Collected Posts', $this->text_domain); $capability = !$this->options->qc_authorization_all_roles_can_modify_settings ? 'manage_options' : $this->options->qc_authorization_who_can_use; $menu_slug = 'collected-posts'; $function = array($this, 'collected_posts_page'); $hook = add_submenu_page($parent_slug, $page_title, $menu_title, $capability, $menu_slug, $function); add_action( "load-$hook", array($this, 'add_collected_posts_page_options') ); } public function add_collected_posts_page_options() { require __DIR__ . DIRECTORY_SEPARATOR. 'classes' . DIRECTORY_SEPARATOR . 'class.Collected_Posts_List_Table.php'; $option = 'per_page'; $args = array( 'label' => __('Number of items per page:'), 'default' => 20, 'option' => 'collected_posts_per_page' ); add_screen_option( $option, $args ); $this->list_table = new \Collected_Posts_List_Table(); } public function set_screen_option($status, $option, $value) { if ($option == 'collected_posts_per_page') return $value; return $status; } function collected_posts_page() { ?>
