 wp_reset_query(); } public function posts_columns(){ $columns = array( 'cb' => '<input type="checkbox" />', 'title' => __('Title'), 'collection_number' => __('Collection Number', $this->text_domain), 'import' => __('Import Links', $this->text_domain), 'manual' => __('Manual Collecting', $this->text_domain), 'schedule' => __('Schedule Collecting', $this->text_domain), 'import_export' => __('Import &amp; Export', $this->text_domain) ); if (!$this->options->qc_display_collected_posts_number) unset($columns['collection_number']); return $columns; } public function count_collected_posts($pid) { $count = $GLOBALS['QC']->cache->get_cache('count_collected_posts_' . $pid); if (!$count) { global $wpdb; $sql = "SELECT COUNT(*) FROM `$wpdb->posts` WHERE `ID` IN (
						SELECT `post_id` FROM `{$wpdb->postmeta}` WHERE
							`post_id` = `$wpdb->posts`.`ID` AND
							`meta_key` = '_collection_project' AND
							`meta_value` = {$pid}
					)"; $count = $wpdb->get_var($sql); $GLOBALS['QC']->cache->set_cache('count_collected_posts_' . $pid, $count, 300); } return $count; } public function posts_custom_columns( $column ) { global $post; switch ($column) { case 'collection_number': $count = $this->count_collected_posts($post->ID); echo $count ? $count : '--'; break; case 'import': $collection_project = get_post_meta($post->ID, 'qqworld-collection-project', true); $links = isset($collection_project['links']) ? $collection_project['links'] : array(); $args = array(); if (!empty($links)) { $links = current($links); if (isset($links['post_type'])) $args['post_type'] = $links['post_type']; if (isset($links['taxonomies'])) $args['taxonomies'] = $links['taxonomies']; if (isset($links['author'])) $args['author'] = $links['author']; $args['settings'] = $collection_project['settings']; } $args = base64_encode(urlencode(json_encode($args, JSON_INVALID_UTF8_IGNORE))); ?>
				<button type="button" data-id="<?php echo $post->ID; ?>" data-args="<?php print $args; ?>" class="button button-primary import-links qc-icon download"><?php _e('Import Links', $this->text_domain); ?></button>
				<label title="<?php _e('Do not filter the collected content, collect all the articles directly! Can effectively reduce browser pressure.', $this->text_domain); ?>"><input type="checkbox" name="extreme-speed" value="1"> <?php _e('Extreme Speed', $this->text_domain); ?></label>
