				<p><?php
 $datetime = get_post_meta($post->ID, 'last-collected-time', true); if ($datetime) { $format = get_option('date_format') . ' ' . get_option('time_format'); $date = date($format, intval($datetime)); } else $date = '--'; printf(__('Lastest collected time: <span class="last-collected-time">%s</span>', $this->text_domain), $date); ?></p>
			<?php break; case 'schedule': printf(__('After %s minutes', $this->text_domain), '<input type="number" class="small-text" id="after-schedule-'.$post->ID.'" name="after-schedule" value="5" />'); ?>
				<select id="schedule-<?php echo $post->ID; ?>" name="schedule" class="selectstyle">
					<option value="" data-interval="0"><?php _e('Single Task', $this->text_domain); ?></option>
				<?php
